import{c as e,J as a,h as o,k as n}from"./chunks/framework.WgZQdPFo.js";const p=JSON.parse('{"title":"Investment Portfolio","description":"Managing stocks, bonds, crypto assets, private equity, and loans with automated P&L returns and multi-level allocation shares.","frontmatter":{"title":"Investment Portfolio","description":"Managing stocks, bonds, crypto assets, private equity, and loans with automated P&L returns and multi-level allocation shares.","order":18},"headers":[],"relativePath":"docs/spaces/moy-kapital/investments.md","filePath":"docs/spaces/moy-kapital/investments.md"}'),i={name:"docs/spaces/moy-kapital/investments.md"};function r(s,t,l,c,d,u){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="investment-portfolio" tabindex="-1">Investment Portfolio <a class="header-anchor" href="#investment-portfolio" aria-label="Permalink to &quot;Investment Portfolio&quot;">​</a></h1><p>The <strong>Investment Portfolio</strong> tab tracks assets designed to preserve and grow your personal wealth: publicly traded equities, government and corporate bonds, investment funds, volatile cryptocurrencies, private business equity, and peer-to-peer loans.</p><p>Unlike standard checking accounts, investment management in OmniCraft ERP continuously tracks your financial return ($P&amp;L$) and percentage yield while accounting for currency fluctuations.</p><hr><h2 id="_3-level-portfolio-hierarchy" tabindex="-1">3-Level Portfolio Hierarchy <a class="header-anchor" href="#_3-level-portfolio-hierarchy" aria-label="Permalink to &quot;3-Level Portfolio Hierarchy&quot;">​</a></h2><p>To maintain order across diverse investment types, OmniCraft ERP enforces a 3-tier hierarchy:</p><p>$$\\text{Asset Class} \\longrightarrow \\text{Platform / Broker} \\longrightarrow \\text{Instruments}$$</p><ol><li><strong>Asset Class (Group Category):</strong> top-level risk diversification bucket (&quot;Equities&quot;, &quot;Fixed Income &amp; Bonds&quot;, &quot;Cryptocurrency&quot;, &quot;Private Equity&quot;, &quot;Loans Issued&quot;).</li><li><strong>Platform / Broker (Account Group):</strong> specific custody location (&quot;Interactive Brokers&quot;, &quot;Hardware Cold Wallet&quot;, &quot;Private Venture №1&quot;).</li><li><strong>Financial Instruments (Positions):</strong> individual holdings (&quot;Apple Inc. (AAPL)&quot;, &quot;Treasury Bond 2030&quot;, &quot;Bitcoin (BTC)&quot;, &quot;25% Studio Equity&quot;).</li></ol><hr><h2 id="portfolio-allocation-bar" tabindex="-1">Portfolio Allocation Bar <a class="header-anchor" href="#portfolio-allocation-bar" aria-label="Permalink to &quot;Portfolio Allocation Bar&quot;">​</a></h2><p>A multi-segment colored bar spans the top of the investment screen:</p><ul><li>Each segment matches the distinct theme color of its asset class.</li><li>Segment length reflects the class&#39;s exact percentage of total portfolio value.</li><li>Hovering over a segment or clicking a legend item displays the converted valuation and exact allocation percentage.</li></ul><div class="tip custom-block"><p class="custom-block-title">Risk Rebalancing</p><p>A well-diversified craftsman portfolio cushions against seasonal slumps in the workshop. If risky asset classes exceed your targeted threshold, the Allocation Bar flags the imbalance immediately.</p></div><hr><h2 id="calculating-p-l-and-multi-level-allocation-shares" tabindex="-1">Calculating P&amp;L and Multi-Level Allocation Shares <a class="header-anchor" href="#calculating-p-l-and-multi-level-allocation-shares" aria-label="Permalink to &quot;Calculating P&amp;L and Multi-Level Allocation Shares&quot;">​</a></h2><p>For each position, the engine calculates:</p><ul><li><strong>Current Value in Base Currency:</strong> real-time market value translated at current exchange rates.</li><li><strong>Financial Result ($P&amp;L$):</strong> $$P&amp;L = \\text{Current Value} - \\text{Invested Capital}$$ Positive returns are highlighted in green; drawdowns appear in clear alert red.</li><li><strong>Percentage Yield:</strong> $$\\text{Yield, %} = \\frac{P&amp;L}{\\text{Invested Capital}} \\times 100%$$</li><li><strong>Multi-Level Percentage Shares:</strong> asset class share in category headers, broker weight in the portfolio, and position share in total wealth (alongside relative weight within the group).</li></ul><hr><h2 id="adding-and-configuring-investments" tabindex="-1">Adding and Configuring Investments <a class="header-anchor" href="#adding-and-configuring-investments" aria-label="Permalink to &quot;Adding and Configuring Investments&quot;">​</a></h2><p>Clicking <strong>&quot;Add&quot;</strong> opens a creation dialog with two operational modes:</p><ol><li><strong>Single Asset:</strong> rapid entry of a standalone contract (such as a promissory loan or angel investment).</li><li><strong>Group / Broker / Platform:</strong> bulk batch entry for an entire brokerage account using the <strong>&quot;Add asset to group&quot;</strong> button.</li></ol><p>The form includes:</p><ul><li>Position title and platform selection.</li><li>Asset class assignment with instant category creation.</li><li>Native currency, exchange rate, and initial invested principal.</li><li>Current market valuation.</li><li>Direct URL links to exchange tickers and private strategic notes.</li></ul><hr><h2 id="platform-management-and-reordering" tabindex="-1">Platform Management and Reordering <a class="header-anchor" href="#platform-management-and-reordering" aria-label="Permalink to &quot;Platform Management and Reordering&quot;">​</a></h2><p>Each broker card includes rapid management tools:</p><ul><li><strong>&quot;+&quot; Button:</strong> instantly adds a new instrument to this platform.</li><li><strong>Up / Down Arrows:</strong> reorder items and platforms to reflect portfolio priorities.</li><li><strong>Pencil Button (Manage Platform):</strong> modal dialog for bulk renaming platforms with cascading updates to child assets, reassigning asset classes, and deleting closed positions.</li><li><strong>View Switcher (&quot;Stripes&quot; / &quot;Grid&quot;):</strong> switch between detailed card grids and high-density summary rows.</li></ul>',27)])])}const h=e(i,[["render",r]]);export{p as __pageData,h as default};
